def readSchemaText(source:str, headers:dict = {})->str:
  '''
  read a schema as text \n
  source: str: an http(s) url, or a local file path such as squirrelSchemaPath \n
  headers: dict: HTTP headers for the get request (ignored for local files)
  '''
  if source.startswith(('http://', 'https://')):
    return requests.get(source, headers=headers).text
  with open(source) as f:
    return f.read()

